WITH promo_stats AS ( SELECT p.p_promo_id, p.p_promo_name, p.p_channel_tv, p.p_channel_email, p.p_channel_radio, SUM(ws.ws_ext_discount_amt) AS total_discount, AVG(ws.ws_ext_discount_amt) AS avg_discount, SUM(ws.ws_net_profit) AS total_net_profit, COUNT(*) AS sale_cnt, SUM(CASE WHEN hd.hd_dep_count > 3 THEN ws.ws_net_profit ELSE 0 END) AS profit_high_dep, COUNT(DISTINCT wp.wp_type) AS distinct_page_types FROM promotion p JOIN web_sales ws ON ws.ws_promo_sk = p.p_promo_sk JOIN household_demographics hd ON ws.ws_ship_hdemo_sk = hd.hd_demo_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk GROUP BY p.p_promo_id, p.p_promo_name, p.p_channel_tv, p.p_channel_email, p.p_channel_radio ) SELECT p_promo_id AS p_id, p_promo_name AS p_name, CASE WHEN p_channel_tv = 'Y' THEN 'TV' WHEN p_channel_email = 'Y' THEN 'Email' WHEN p_channel_radio = 'Y' THEN 'Radio' ELSE 'Other' END AS primary_channel, total_discount, avg_discount, total_net_profit, profit_high_dep, distinct_page_types, DENSE_RANK() OVER (ORDER BY avg_discount DESC) AS discount_rank FROM promo_stats ORDER BY discount_rank LIMIT 15
